// IMPORTAR
const fs = require('fs');

// CRIA O ARRAY COM OS 5 SENSORES
const sensores = [
  { codigo: 101, tipo: "Temperatura", valor: 85.5, unidade: "°C", status: "Alerta" },
  { codigo: 102, tipo: "Pressao", valor: 2.1, unidade: "bar", status: "Normal" },
  { codigo: 103, tipo: "Vibracao", valor: 12.0, unidade: "mm/s", status: "Alerta" },
  { codigo: 104, tipo: "Nivel", valor: 75.0, unidade: "%", status: "Normal" },
  { codigo: 105, tipo: "Fluxo", valor: 0.0, unidade: "L/min", status: "Alerta" }
];

// CONVERTE O ARRAY PARA JSON E SALVA NO ARQUIVO
const dadosJson = JSON.stringify(sensores, null, 2);
fs.writeFileSync('monitoramento.json', dadosJson);


console.log("Arquivo monitoramento.json criado com sucesso!");


//   ==================================================================
//   RESUMO DOS COMANDOS USADOS:
//   ==================================================================

//   1. JSON.stringify(sensores, null, 2):
//      - Converte o array de sensores em texto para poder salvar.

//   2. fs.writeFileSync('monitoramento.json', dadosJson):
//      - Cria o arquivo e grava os dados no computador.